const distance=(a,b)=>(Math.abs(a[0]-b[0])+Math.abs(a[1]-b[1])+Math.abs(a[2]-b[2]))/765;
const hex=a=>'#'+a.map(v=>Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')).join('');
export function inspectTextStyle(pixels,width,height,box){
 const left=Math.max(1,Math.floor(box.x*width)),top=Math.max(1,Math.floor(box.y*height)),right=Math.min(width-2,Math.ceil((box.x+box.w)*width)),bottom=Math.min(height-2,Math.ceil((box.y+box.h)*height));if(right<=left||bottom<=top)return null;
 const rgb=(x,y)=>{const i=(Math.max(0,Math.min(height-1,y))*width+Math.max(0,Math.min(width-1,x)))*4;return[pixels[i],pixels[i+1],pixels[i+2]]},border=[];for(let x=left;x<=right;x+=3){border.push(rgb(x,top-6),rgb(x,bottom+6))}for(let y=top;y<=bottom;y+=3)border.push(rgb(left-6,y),rgb(right+6,y));const bg=[0,1,2].map(c=>border.map(v=>v[c]).sort((a,b)=>a-b)[Math.floor(border.length/2)]),bins=new Map();
 for(let y=top;y<=bottom;y++)for(let x=left;x<=right;x++){const color=rgb(x,y);if(distance(color,bg)<.16)continue;const key=color.map(v=>v>>5).join(',');let b=bins.get(key);if(!b){b={count:0,total:[0,0,0]};bins.set(key,b)}b.count++;for(let c=0;c<3;c++)b.total[c]+=color[c]}
 const palette=[...bins.values()].sort((a,b)=>b.count-a.count).map(b=>({color:b.total.map(v=>v/b.count),count:b.count}));if(!palette.length||palette[0].count<20)return null;const fill=palette[0],edge=palette.slice(1).find(p=>p.count>Math.max(12,fill.count*.12)&&distance(p.color,fill.color)>.22);const result={fill:hex(fill.color),background:hex(bg),edge:null,type:'fill-only',support:0};if(!edge)return result;
 const quadrants=[0,0,0,0];let sx=0,sy=0,n=0,examined=0;const stride=Math.max(2,Math.ceil(Math.sqrt((right-left)*(bottom-top)/500)));
 for(let y=top;y<=bottom;y+=stride)for(let x=left;x<=right;x+=stride){if(distance(rgb(x,y),fill.color)>.08)continue;examined++;let best=null;for(let dy=-5;dy<=5;dy++)for(let dx=-5;dx<=5;dx++){if(!dx&&!dy)continue;const d=Math.hypot(dx,dy);if(d>5||best&&d>=best.d)continue;if(distance(rgb(x+dx,y+dy),edge.color)<.08)best={dx,dy,d}}if(best){n++;sx+=best.dx;sy+=best.dy;quadrants[best.dx>=0?(best.dy>=0?0:1):(best.dy>=0?2:3)]++}}
 if(n<10||n/Math.max(1,examined)<.18)return result;result.edge=hex(edge.color);result.support=n/Math.max(1,examined);const balanced=quadrants.filter(c=>c/n>.12).length>=3;result.type=balanced?'outline-candidate':'shadow-or-outline';result.offset={x:sx/n,y:sy/n};return result;
}
